#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_prepend_enough_space_no_resize(void) {
    // Setup: create a buffer with enough space to prepend without resizing
    // We'll create a buffer with allocation size 32 and content "World"
    buffer_t *buf = buffer_new_with_size(32);
    TEST_ASSERT_NOT_NULL(buf);
    strcpy(buf->data, "World");
    // Set the string length field if needed (commonly buf->len)
    buf->len = strlen("World");

    // Test: prepend "Hello " to the buffer
    int ret = buffer_prepend(buf, "Hello ");
    TEST_ASSERT_EQUAL_INT(0, ret);

    // Assert: buffer content is now "Hello World"
    helper_assert_buffer_content(buf, "Hello World");
    // Assert: buffer string length is 11
    helper_assert_buffer_length(buf, 11);
    // Assert: buffer size is still 32 (no resize)
    helper_assert_buffer_size(buf, 32);

    // Cleanup
    helper_free_buffer(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_prepend_enough_space_no_resize);
    return UNITY_END();
}


